package local.tv.quranidle;
import android.app.Service;import android.content.*;import android.database.ContentObserver;import android.media.*;import android.os.*;import android.provider.Settings;import android.util.Log;
final class AdhanPlayer {
 private final Service c;private final AudioManager audio;private final Handler h=new Handler(Looper.getMainLooper());private MediaPlayer player;private AudioFocusRequest focus;private boolean active,wasMuted;private int before=-1;
 private final ContentObserver observer=new ContentObserver(h){public void onChange(boolean self){if(active&&audio.getStreamVolume(AudioManager.STREAM_MUSIC)>7)audio.setStreamVolume(AudioManager.STREAM_MUSIC,7,0);}};
 AdhanPlayer(Service context){c=context;audio=c.getSystemService(AudioManager.class);c.getContentResolver().registerContentObserver(Settings.System.CONTENT_URI,true,observer);}
 void play(boolean fajr,boolean test){if(active)return;active=true;AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(attrs).setOnAudioFocusChangeListener(f->{if(f==AudioManager.AUDIOFOCUS_LOSS)stop();}).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){active=false;Log.w("AdhanSeven","no-audio-focus");return;}
 h.postDelayed(()->{if(!active)return;try{wasMuted=audio.isStreamMute(AudioManager.STREAM_MUSIC);if(wasMuted)audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_UNMUTE,0);before=audio.getStreamVolume(AudioManager.STREAM_MUSIC);audio.setStreamVolume(AudioManager.STREAM_MUSIC,Math.min(7,audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)),0);player=new MediaPlayer();player.setAudioAttributes(attrs);player.setWakeMode(c,PowerManager.PARTIAL_WAKE_LOCK);try(android.content.res.AssetFileDescriptor fd=c.getAssets().openFd(fajr?"fajr.mp3":"adhan.mp3")){player.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());}player.setOnPreparedListener(p->{if(active){audio.setStreamVolume(AudioManager.STREAM_MUSIC,7,0);p.start();Log.i("AdhanSeven","playing-volume-"+audio.getStreamVolume(AudioManager.STREAM_MUSIC));}});player.setOnCompletionListener(p->stop());player.setOnErrorListener((p,w,e)->{Log.w("AdhanSeven","error-"+w+"-"+e);stop();return true;});player.prepareAsync();if(test)h.postDelayed(this::stop,12000);else h.postDelayed(this::stop,10*60000);}catch(Exception e){Log.e("AdhanSeven","failed",e);stop();}},250);}
 void stop(){active=false;h.removeCallbacksAndMessages(null);if(player!=null){player.release();player=null;}if(focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(before>=0){if(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==7)audio.setStreamVolume(AudioManager.STREAM_MUSIC,before,0);if(wasMuted)audio.adjustStreamVolume(AudioManager.STREAM_MUSIC,AudioManager.ADJUST_MUTE,0);before=-1;}Log.i("AdhanSeven","stopped");}
 void close(){stop();c.getContentResolver().unregisterContentObserver(observer);}
}
